// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address fakeCollateral, address fakeDebt) public {
        vm.assume(uint160(fakeCollateral) != uint160(fakeDebt));

        // Reproduce the immutable-args tail appended to a clone's calldata:
        // owner (0x00), collateral (0x14), debt (0x28), factory (0x3c), then uint16 length 0x50.
        bytes memory tail = abi.encodePacked(
            address(0x1234),
            fakeCollateral,
            fakeDebt,
            address(0x5678),
            uint16(0x50)
        );

        bytes memory callData = abi.encodePacked(
            c.collateral.selector,
            tail
        );

        (bool ok, bytes memory ret) = address(c).call(callData);
        assertTrue(ok && address(uint160(uint256(bytes32(ret)))) == fakeCollateral);
    }
}
